insert into public.neighbourhoods (slug,name,tagline_en,tagline_vi,description_en,description_vi,image,sort_order) values ('tay-ho','Tây Hồ','Lakeside living, at your pace.','An yên bên hồ, theo nhịp của bạn.','Morning walks by West Lake. Coffee on a quiet side street. Discover homes in one of Hanoi’s best-known lakeside neighbourhoods.','Dạo bộ bên Hồ Tây mỗi sáng, thưởng thức cà phê trong những con ngõ yên tĩnh. Khám phá không gian sống bên hồ giữa lòng Hà Nội.','/images/area-tay-ho.jpg',0) on conflict (slug) do nothing;
insert into public.neighbourhoods (slug,name,tagline_en,tagline_vi,description_en,description_vi,image,sort_order) values ('ba-dinh','Ba Đình','The city’s history. Your new story.','Nét xưa của phố. Câu chuyện mới của bạn.','Tree-lined streets, familiar local markets, and the city’s historic heart. Explore apartments around Đào Tấn, Kim Mã, and Đội Cấn.','Những con phố rợp bóng cây, khu chợ thân quen và trái tim lịch sử của thành phố. Khám phá căn hộ quanh Đào Tấn, Kim Mã và Đội Cấn.','/images/area-ba-dinh.jpg',1) on conflict (slug) do nothing;
insert into public.neighbourhoods (slug,name,tagline_en,tagline_vi,description_en,description_vi,image,sort_order) values ('long-bien','Long Biên','A little more space to breathe.','Thêm không gian để tận hưởng.','Across the Red River, discover a different rhythm of Hanoi. Explore homes in Ngọc Thụy and the surrounding residential neighbourhoods.','Bên kia sông Hồng là một nhịp sống Hà Nội khác. Khám phá nhà ở tại Ngọc Thụy và các khu dân cư lân cận.','/images/area-long-bien.jpg',2) on conflict (slug) do nothing;
insert into public.neighbourhoods (slug,name,tagline_en,tagline_vi,description_en,description_vi,image,sort_order) values ('bac-tu-liem','Bắc Từ Liêm','A fresh start, within reach.','Khởi đầu mới, trong tầm tay.','Find your own corner of western Hanoi, with studios and apartments to suit a range of budgets.','Tìm góc riêng của bạn tại phía Tây Hà Nội với các căn studio và căn hộ phù hợp nhiều mức ngân sách.','/images/area-bac-tu-liem.jpg',3) on conflict (slug) do nothing;
